-- Passage rg10-story-details-inference-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f3466347-0c3a-58a9-85ea-589f2924bad5', 'rg10-story-details-inference-p03', (select id from public.skills where slug = 'read-g10-story-details-inference'), null,
        '9-12', $q$Night Plow$q$, $q$At two in the morning the town is a held breath.
Snow has filled the streets to the curbs
and erased the painted lines that tell us where to stop.
Mr. Haddad starts the orange truck behind the depot.
The engine coughs twice, then settles into a hum.

He drives the same loop he has driven for nineteen winters:
Maple, then Water Street, then the hill by the clinic,
where he lowers the blade a little farther
because the nurses park there before the sun is up.
He knows which mailbox leans, which hydrant hides,
which porch light stays on for someone working late.

Nobody waves. Nobody is awake to wave.
Behind him the road opens like a page turned back to blank,
and the salt hisses on the black pavement
in a voice only he has ever heard.

At six the bakery lights come on.
At seven the buses pull out, one by one,
their tires finding the lines he cannot see.
Children press their mittens to the windows
and talk about the snow as if it had simply stopped,
as if the streets had cleared themselves at dawn.

Mr. Haddad parks the truck and fills out his log:
miles driven, salt used, time returned.
There is no line on the form for the clinic hill,
so he does not write it down.
He walks home on the street he cleared,
his boots making the first prints in the new dust,
and goes to sleep while the town wakes up.$q$, 'draft')
