  ('32dea07b-9404-556c-b273-dd1d3635dee8', null, (select id from public.skills where slug = 'read-g10-story-details-inference'), null, 'medium',
   $q$Which evidence best supports the inference that Ravi grew more confident and skilled after midnight?$q$, $q$[{"text":"He stopped worrying about how he sounded and logged ninety-one contacts in two hours.","is_correct":true},{"text":"Mrs. Ostrowski fell asleep in her folding chair holding the bag of seeds.","is_correct":false,"misconception_token":"weak-evidence"},{"text":"He forgot the club's call sign twice and mixed up two of the states.","is_correct":false,"misconception_token":"wrong-time-period"},{"text":"Signals that had been faint came in strong from operators all over the country.","is_correct":false,"misconception_token":"weak-evidence"}]$q$::jsonb, $q$He stopped worrying about how he sounded and logged ninety-one contacts in two hours.$q$, $q$Both details in the correct choice describe Ravi himself: a change in his attitude and a large jump in what he accomplished. Stronger signals explain why more contacts were possible, but they say nothing about Ravi's own growth.$q$, 'draft', 'a6a05ab9-b449-5c56-ae70-4422edf5b9f8')
